class DecodeFailure final : public std::runtime_error {
public:
    explicit DecodeFailure(Diagnostic diagnostic)
        : std::runtime_error(diagnostic.message), diagnostic_(std::move(diagnostic)) {}

    [[nodiscard]] const Diagnostic& diagnostic() const noexcept {
        return diagnostic_;
    }

private:
    Diagnostic diagnostic_;
};

std::string child_path(std::string_view parent, std::size_t index) {
    return std::string(parent) + "/" + std::to_string(index);
}

std::string_view without_utf8_bom(std::string_view text) noexcept {
    constexpr std::string_view bom{"\xef\xbb\xbf", 3};
    return text.starts_with(bom) ? text.substr(bom.size()) : text;
}

std::string describe(const list_stream::ListValue& value) {
    std::string actual = list_stream::dump_compact(value);
    constexpr std::size_t limit = 120;
    if (actual.size() > limit) {
        actual.resize(limit);
        actual += "...";
    }
    return actual;
}

[[noreturn]] void fail(
    std::string code,
    std::string path,
    std::string expected,
    std::string actual,
    std::string message) {
    throw DecodeFailure(Diagnostic{
        std::move(code),
        DiagnosticSeverity::error,
        {},
        std::move(path),
        {},
        std::move(expected),
        std::move(actual),
        std::move(message),
    });
}

void require_list(const list_stream::ListValue& value, std::string_view path) {
    if (!value.is_list) {
        fail(
            "OOF1101",
            std::string(path),
            "list",
            describe(value),
            "Storage record must be a list");
    }
}

void require_arity(
    const list_stream::ListValue& value,
    std::size_t arity,
    std::string_view path) {
    require_list(value, path);
    if (value.items.size() != arity) {
        fail(
            "OOF1102",
            std::string(path),
            "list arity " + std::to_string(arity),
            "list arity " + std::to_string(value.items.size()),
            "Storage record has unexpected arity");
    }
}

constexpr std::string_view null_uuid = "00000000-0000-0000-0000-000000000000";

// Bindings keep the real local root identity. A metadata leaf domain is optional
// when its control stores only member identity rather than a value type.
struct ResolvedBinding {
    std::string name;
    std::optional<model::TypeDomainPatternValue> type;
    model::DataPath data_path;

    const model::TypeDomainPatternValue& required_type() const {
        if (!type)
            fail("OOF1123", "$/DataPath/Member/TypeDomain", "explicit member leaf type", "absent",
                "This control requires a self-contained DataPath member type");
        return *type;
    }
};

// These standard members are verified for CatalogItem object context only.
constexpr std::array<std::pair<std::string_view, std::int64_t>, 3> catalog_standard_members{{
    {"Code", -2}, {"Description", -3}, {"Parent", -4},
}};

bool catalog_member_root(const model::Form& form, const model::DataPath& path) {
    return form.extension == model::FormExtensionKind::catalog_item &&
        form.main_attribute.has_value() && path.attribute == form.main_attribute;
}

std::vector<MetadataMemberKey> encode_binding_members(
    const model::Form& form, const model::DataPath& path) {
    std::vector<MetadataMemberKey> keys;
    bool catalog_family = catalog_member_root(form, path);
    for (std::size_t index = 0; index < path.members.size(); ++index) {
        const auto& member = path.members[index];
        if (member.uuid) {
            keys.emplace_back(*member.uuid);
            catalog_family = false;
            continue;
        }
        const auto standard = std::ranges::find(catalog_standard_members, member.name,
            &decltype(catalog_standard_members)::value_type::first);
        if (!catalog_family || standard == catalog_standard_members.end())
            fail("OOF1123", "$/DataPath/Member", "metadata member UUID or known CatalogItem standard member",
                member.name, "Named metadata member has no supported serialized identity");
        keys.emplace_back(standard->second);
        if (member.name != "Parent" && index + 1 != path.members.size())
            fail("OOF1123", "$/DataPath/Member", "terminal Code or Description member", member.name,
                "Only Parent preserves the CatalogItem member family for further segments");
    }
    return keys;
}

std::optional<ResolvedBinding> resolve_attribute_reference(
    const model::OrdinaryFormDocument& document,
    const model::DataPath& path) {
    const auto* root = path.attribute.has_value() ? document.find_attribute(path.attribute.id()) : nullptr;
    if (!root) return std::nullopt;
    ResolvedBinding binding{root->name, root->type, path};
    if (path.members.empty()) return binding;
    (void)encode_binding_members(document.form(), path);
    for (const auto& member : path.members) {
        if (!member.name.empty()) binding.name += "." + member.name;
    }
    binding.type = path.members.back().type;
    return binding;
}

const list_stream::ListValue& at(
    const list_stream::ListValue& value,
    std::size_t index,
    std::string_view path) {
    require_list(value, path);
    if (index >= value.items.size()) {
        fail(
            "OOF1103",
            child_path(path, index),
            "existing record slot",
            "missing",
            "Storage record slot is missing");
    }
    return value.items[index];
}

std::string raw_atom(const list_stream::ListValue& value, std::string_view path) {
    if (value.is_list || value.atom_kind != list_stream::ListValue::AtomKind::raw) {
        fail(
            "OOF1104",
            std::string(path),
            "raw atom",
            describe(value),
            "Storage slot has unexpected value kind");
    }
    return value.atom;
}

std::string string_atom(const list_stream::ListValue& value, std::string_view path) {
    if (value.is_list || value.atom_kind != list_stream::ListValue::AtomKind::string) {
        fail(
            "OOF1104",
            std::string(path),
            "string atom",
            describe(value),
            "Storage slot has unexpected value kind");
    }
    return value.atom;
}

template <typename Integer>
Integer integer_atom(const list_stream::ListValue& value, std::string_view path) {
    const std::string atom = raw_atom(value, path);
    Integer result{};
    const char* const begin = atom.data();
    const char* const end = begin + atom.size();
    const auto parsed = std::from_chars(begin, end, result, 10);
    if (atom.empty() || parsed.ec != std::errc{} || parsed.ptr != end) {
        fail(
            "OOF1105",
            std::string(path),
            "base-10 integer",
            atom,
            "Storage integer is malformed or out of range");
    }
    return result;
}

bool bool_atom(const list_stream::ListValue& value, std::string_view path) {
    const std::uint32_t parsed = integer_atom<std::uint32_t>(value, path);
    if (parsed > 1) {
        fail(
            "OOF1105",
            std::string(path),
            "0 or 1",
            std::to_string(parsed),
            "Storage Boolean is malformed");
    }
    return parsed != 0;
}

void require_raw_constant(
    const list_stream::ListValue& value,
    std::string_view expected,
    std::string_view path) {
    const std::string actual = raw_atom(value, path);
    if (actual != expected) {
        fail(
            "OOF1106",
            std::string(path),
            std::string(expected),
            actual,
            "Storage constant does not match the record contract");
    }
}

model::UuidValue uuid_atom(const list_stream::ListValue& value, std::string_view path) {
    try {
        list_stream::ListInStream in(value);
        return model::UuidValue{in.read_guid()};
    } catch (const std::exception& error) {
        fail(
            "OOF1105",
            std::string(path),
            "canonical UUID atom",
            describe(value),
            error.what());
    }
}

