DecodedControl decode_default_complex_control(
    const LV& record, std::string_view path, const GeometryContext& context,
    model::ControlKind kind, Diagnostics& warnings, bool& reconstruction_complete) {
    const auto& descriptor = model::metamodel::descriptor_for(kind);
    const auto geometry_slot = control_geometry_slot(descriptor.guid);
    require_arity(record, geometry_slot + 3, path);
    require_raw_constant(record.items[0], descriptor.guid, child_path(path, 0));
    const auto id = integer_atom<std::uint64_t>(record.items[1], child_path(path, 1));
    if (id == 0 || id > static_cast<std::uint64_t>(std::numeric_limits<std::int64_t>::max()))
        fail("OOF1122", child_path(path, 1), "positive int64 control ID", std::to_string(id), "Default complex control ID is invalid");
    std::vector<DecodedControlEvent> named_events;
    model::ColorValue border_color;
    std::int32_t output = 0;
    auto back_color = chart_back_color_default();
    std::int32_t pivot_chart_type = 1;
    if (kind == model::ControlKind::graphical_schema_field) {
        require_arity(record.items[2], 6, child_path(path, 2));
        auto normalized_info = record.items[2];
        read_common_control_base(normalized_info.items[0], child_path(child_path(path, 2), 0), [] {
            return canonical_graphical_schema_field_info().items[0];
        }, {warnings, id, "GraphicalSchemaField", CommonControlBaseStatePolicy::strict_default_layouts});
        border_color = decode_control_color(normalized_info.items[0].items[6], child_path(child_path(child_path(path, 2), 0), 6));
        normalized_info.items[0].items[6] = canonical_graphical_schema_field_info().items[0].items[6];
        named_events = decode_control_event_collection(normalized_info.items[3], child_path(child_path(path, 2), 3), kind);
        normalized_info.items[3] = list({raw("0")});
        output = integer_atom<std::int32_t>(normalized_info.items[5], child_path(child_path(path, 2), 5));
        normalized_info.items[5] = raw("0");
        if (list_stream::dump_compact(normalized_info) != list_stream::dump_compact(canonical_graphical_schema_field_info()))
            warn_incomplete_profile(warnings, reconstruction_complete, id, child_path(path, 2), "GraphicalSchemaField");
    } else if (kind == model::ControlKind::pivot_chart) {
        require_arity(record.items[2], 13, child_path(path, 2));
        require_raw_constant(record.items[2].items[0], "3", child_path(child_path(path, 2), 0));
        auto normalized_info = record.items[2];
        require_arity(normalized_info.items[1], 3, child_path(child_path(path, 2), 1));
        const auto renderer_path = child_path(child_path(child_path(path, 2), 1), 2);
        const auto& renderer = normalized_info.items[1].items[2];
        require_arity(renderer, 386, renderer_path);
        require_raw_constant(renderer.items[0], "75", child_path(renderer_path, 0));
        require_raw_constant(renderer.items[4], "4", child_path(renderer_path, 4));
        require_raw_constant(renderer.items[61], "4", child_path(renderer_path, 61));
        pivot_chart_type = integer_atom<std::int32_t>(normalized_info.items[6], child_path(child_path(path, 2), 6));
        if (pivot_chart_type < 0 || pivot_chart_type > 1)
            fail("OOF1114", child_path(child_path(path, 2), 6), "PivotChartType ordinal 0 or 1", {}, "Unknown PivotChartType");
        require_raw_constant(renderer.items[108], pivot_chart_type == 0 ? "4" : "6", child_path(renderer_path, 108));
        normalized_info.items[6] = raw("1");
        normalized_info.items[1].items[2].items[108] = raw("6");
        back_color = decode_chart_back_color(renderer, 127, 378, renderer_path);
        encode_chart_back_color(normalized_info.items[1].items[2], 127, 378, {}, "$/PivotChart/BackColor");
        if (list_stream::dump_compact(normalized_info) != list_stream::dump_compact(canonical_default_pivot_chart_info()))
            warn_incomplete_profile(warnings, reconstruction_complete, id, child_path(path, 2), "PivotChart");
    } else {
        auto normalized_info = record.items[2];
        read_common_control_base(normalized_info, child_path(path, 2), [] {
            return canonical_geographical_schema_field_info();
        }, {warnings, id, "GeographicalSchemaField", CommonControlBaseStatePolicy::strict_default_layouts});
        border_color = decode_control_color(normalized_info.items[6], child_path(child_path(path, 2), 6));
        normalized_info.items[6] = canonical_geographical_schema_field_info().items[6];
        if (list_stream::dump_compact(normalized_info) != list_stream::dump_compact(canonical_geographical_schema_field_info()))
            warn_incomplete_profile(warnings, reconstruction_complete, id, child_path(path, 2), "GeographicalSchemaField");
        auto normalized_schema = record.items[3];
        require_arity(normalized_schema, 5, child_path(path, 3));
        named_events = decode_control_event_collection(normalized_schema.items[3], child_path(child_path(path, 3), 3), kind);
        normalized_schema.items[3] = list({raw("0")});
        output = integer_atom<std::int32_t>(normalized_schema.items[4], child_path(child_path(path, 3), 4));
        normalized_schema.items[4] = raw("0");
        if (list_stream::dump_compact(normalized_schema) != list_stream::dump_compact(canonical_geographical_schema()))
            warn_incomplete_profile(warnings, reconstruction_complete, id, child_path(path, 3), "GeographicalSchemaField");
    }
    if (output < 0 || output > 2)
        fail("OOF1114", kind == model::ControlKind::graphical_schema_field ?
            child_path(child_path(path, 2), 5) : child_path(child_path(path, 3), 4),
            "Output storage value 0, 1, or 2", std::to_string(output),
            "Schema field Output storage value is unsupported");
    auto geometry = decode_geometry(record.items[geometry_slot], child_path(path, geometry_slot), context);
    const auto metadata_slot = geometry_slot + 1;
    const auto& metadata = record.items[metadata_slot];
    const auto metadata_path = child_path(path, metadata_slot);
    require_arity(metadata, 6, metadata_path);
    const auto name = string_atom(metadata.items[1], child_path(metadata_path, 1));
    if (name.empty()) fail("OOF1115", child_path(metadata_path, 1), "non-empty control name", "empty", "Default complex control name is required");
    require_exact(record.items[geometry_slot + 2], list({raw("0")}), child_path(path, geometry_slot + 2),
        "Default complex control cannot contain form controls");
    model::ControlPayload payload = kind == model::ControlKind::graphical_schema_field
        ? model::ControlPayload{model::GraphicalSchemaFieldPayload{}}
        : kind == model::ControlKind::pivot_chart
        ? model::ControlPayload{model::PivotChartPayload{}}
        : model::ControlPayload{model::GeographicalSchemaFieldPayload{}};
    model::ControlNode control{model::ObjectId{id}, name, std::move(payload)};
    decode_control_metadata(metadata, metadata_path, control);
    if (output != 0) {
        constexpr std::array<std::string_view, 3> members{"Auto", "Enable", "Disable"};
        control.properties().set_explicit(model::PropertyId::from_name("Output"),
            model::EnumerationValue{"Output", std::string(members[static_cast<std::size_t>(output)])});
    }
    if (border_color != model::ColorValue{}) control.properties().set_explicit(model::PropertyId::from_name("BorderColor"), border_color);
    if (kind == model::ControlKind::pivot_chart && back_color != chart_back_color_default()) control.properties().set_explicit(model::PropertyId::from_name("BackColor"), back_color);
    if (kind == model::ControlKind::pivot_chart && pivot_chart_type == 0)
        control.properties().set_explicit(model::PropertyId::from_name("PivotChartType"),
            model::EnumerationValue{"PivotChartType", "Column"});
    control.position = std::move(geometry.position);
    return {std::move(control), std::nullopt, std::move(geometry.incoming), std::nullopt, {}, std::move(named_events)};
}

