LV encode_default_complex_control(const model::OrdinaryFormDocument& document, const model::ControlNode& control, const GeometryContext& context) {
    const auto& descriptor = model::metamodel::descriptor_for(control.kind());
    const std::string path = "$/" + std::string(descriptor.public_name);
    if (control.id.value() == 0 || control.id.value() > static_cast<std::uint64_t>(std::numeric_limits<std::int64_t>::max()))
        fail("OOF1122", path, "positive int64 control ID", std::to_string(control.id.value()), "Default complex control ID is invalid");
    if (control.name.empty() || control.data_path ||
        !control.children.empty() || (control.kind() == model::ControlKind::pivot_chart && !control.events.empty()))
        fail("OOF1122", path, "named default complex control without DataPath, unsupported events, or children", control.name,
            "Default complex control uses an unsupported storage concept");
    if (control.kind() == model::ControlKind::pivot_chart) {
        require_allowed_properties(control.properties(), {"BackColor", "PivotChartType"}, path);
    } else {
        require_allowed_properties(control.properties(), {"BorderColor", "Output"}, path);
    }
    std::vector<LV> fields{raw(std::string(descriptor.guid)), raw(std::to_string(control.id.value()))};
    if (control.kind() == model::ControlKind::graphical_schema_field) {
        fields.push_back(canonical_graphical_schema_field_info());
        fields.back().items[0].items[6] = encode_control_color(explicit_control_color(control.properties(), "BorderColor", "GraphicalSchemaField"), path + "/BorderColor");
        fields.back().items[3] = encode_control_event_collection(document, control, path + "/Events");
        fields.back().items[5] = raw(std::to_string(explicit_enum_storage_value(control.properties(),
            "GraphicalSchemaField", "Output", "Output", 0, {{"Auto", 0}, {"Enable", 1}, {"Disable", 2}})));
    } else if (control.kind() == model::ControlKind::pivot_chart) {
        fields.push_back(canonical_default_pivot_chart_info());
        const auto type = explicit_enum_storage_value(control.properties(), "PivotChart", "PivotChartType", "PivotChartType", 1,
            {{"Column", 0}, {"Column3D", 1}});
        fields.back().items[6] = raw(std::to_string(type));
        fields.back().items[1].items[2].items[108] = raw(type == 0 ? "4" : "6");
        encode_chart_back_color(fields.back().items[1].items[2], 127, 378, control.properties(), path + "/BackColor");
    } else {
        fields.push_back(canonical_geographical_schema_field_info());
        fields.back().items[6] = encode_control_color(explicit_control_color(control.properties(), "BorderColor", "GeographicalSchemaField"), path + "/BorderColor");
        fields.push_back(canonical_geographical_schema());
        fields.back().items[3] = encode_control_event_collection(document, control, path + "/Events");
        fields.back().items[4] = raw(std::to_string(explicit_enum_storage_value(control.properties(),
            "GeographicalSchemaField", "Output", "Output", 0, {{"Auto", 0}, {"Enable", 1}, {"Disable", 2}})));
    }
    fields.push_back(encode_geometry(control.position, context, IncomingAnchorLists{}));
    fields.push_back(encode_control_metadata(control, path));
    fields.push_back(list({raw("0")}));
    return list(std::move(fields));
}

